function fixBreak = exp_checkBreak(screen, EL)% check eyelink for x and y parameters of last guess% output: whether or not fixation was brokenppd = screen.ppd;EL.fixMax = 1; % maximum fixation check timeEL.fixCorrectMin = 0.20; % minimum correct fixation timeEL.fix_radian = 1.5*ppd;t_start = GetSecs;t_current = t_start;t_correct = 0; % time stamp for correct fixationcorrect = 0;% control the timewhile (t_current-t_start < EL.fixMax) && (t_correct <= EL.fixCorrectMin)    % get the current radian    real_radian_pupil = getRealRadian(EL,1,screen);    real_radian_mouse = getRealRadian(EL,2,screen);    real_radian = real_radian_mouse;        if real_radian > EL.fix_radian        fixBreak = 1;        Eyelink('Message', sprintf('BROKE FIXATION'));    else, fixBreak = 0;    end        if fixBreak        if ~correct, t_correct = GetSecs; correct = 1;        elseif correct == 1, t_correct = GetSecs - t_correct;        end    else, correct = 0;    end        t_current = GetSecs;end